const integer=(n,min=0,max=Number.MAX_SAFE_INTEGER)=>assert(Number.isSafeInteger(n)&&n>=min&&n<=max,'Finite integer bounds');
const descriptor=d=>assert(d&&typeof d.path==='string'&&/^[a-f0-9]{64}$/.test(d.sha256),'Exact descriptor');
const freeze=q=>{if(q&&typeof q==='object'&&!Object.isFrozen(q)){Object.values(q).forEach(freeze);Object.freeze(q);}return q;};

/** One byte/JSON cache per batch, keyed by the actual file. Every alias keeps
 * its binding; final verification rehashes each physical file exactly once. */
export function createBatchReader(){const physical=new Map(),aliases=new Map(),bindings={};let parses=0,reads=0;return{
 bindings,async bytes(p){let k=aliases.get(p);if(!k){k=await fs.realpath(p);aliases.set(p,k);}let row=physical.get(k);if(!row){const bytes=await fs.readFile(k);reads++;row={bytes,sha256:sha(bytes)};physical.set(k,row);}if(bindings[p])assert.equal(bindings[p],row.sha256);bindings[p]=row.sha256;return row.bytes;},
 async bound(d){descriptor(d);const bytes=await this.bytes(d.path);assert.equal(sha(bytes),d.sha256,d.path);const row=physical.get(aliases.get(d.path));if(!row.json){row.json=JSON.parse(bytes);parses++;}return row.json;},
 async read(p){return this.bound({path:p,sha256:sha(await this.bytes(p))});},
 async map(m){for(const[p,h]of Object.entries(m??{}))assert.equal(sha(await this.bytes(p)),h,p);},
 async finish(){for(const[p,row]of physical)assert.equal(sha(await fs.readFile(p)),row.sha256,'Bound file drift '+p);},
 stats(){return{physicalReads:reads,jsonParses:parses,physicalFiles:physical.size,aliasBindings:Object.keys(bindings).length};}
};}

