   if(await exists(claim.resultFile)){constructionPaths.push(claim.resultFile);allowed.push(claim.resultFile);const raw=JSON.parse(await fs.readFile(claim.resultFile)),closure={id:p.experimentId,descriptor:await fd(claim.resultFile),raw,closed:true,restartAllowed:false,consumedInputs:candidates.length,maximumInputs:p.maximumInputs};const constructionOwner=await owner(out+'/construction.owner.definition.json',x,p,d,'construction',constructionPaths,[],[closure]),mathOwner=await owner(out+'/math.owner.definition.json',x,p,d,'mathematical',mathPaths,candidates.filter(q=>q.attempt).map(q=>q.attempt.id));try{await members(x.h,allowed);}catch(e){finalizationError??=e.message;}await write(out+'/completion.json',{status:'WHOLEBOARD_BATCH_TASK_CLOSED',plan:d,receipts,constructionOwner,mathOwner,publicClaimsStarted:candidates.filter(q=>q.attempt).length,accepted:candidates.filter(q=>q.accepted).length,formedFullWorlds:formedWorldFiles.length,maximumInputs:p.maximumInputs,consumedInputs:candidates.length,externalOwnerIndexOnly:true,closed:true,finalizationError,historyLoads:1,runtimeLoads:1,readerStats:x.r.stats(),historyIndexStats:x.index.stats()});}
