/** Independently checks stored original-model receipts. It never constructs a
 * source domain, instantiates a model, replays a route or calls a solver. */
export async function auditWholeBoardBatch(mode,d,out){assert(['plan','actual'].includes(mode));assert(!await exists(out));const r=createBatchReader(),subject=await r.bound(d),pd=mode==='plan'?d:subject.plan,p=await r.bound(pd),x=await context(p.contextDescriptor,{deferMembers:mode==='actual'}),errors=[],candidates=[],allowed=[];
 try{assert.deepEqual(p,prepared(x,p.contextDescriptor));if(mode==='actual'){assert.equal(subject.status,'WHOLEBOARD_BATCH_TASK_CLOSED');assert.equal(subject.closed,true);assert.equal(subject.externalOwnerIndexOnly,true);assert.equal(subject.finalizationError,null);assert.equal(subject.maximumInputs,p.maximumInputs);assert.equal(subject.consumedInputs,p.maximumInputs);assert.equal(subject.receipts.length,p.maximumInputs);assert.equal(subject.historyLoads,1);assert.equal(subject.runtimeLoads,1);
   for(const [i,cd]of subject.receipts.entries()){const q=await r.bound(cd),pr=x.preparedRecipes[i],recipe=pr.recipe;candidates.push(q);assert.deepEqual(q.plan,pd);assert.equal(q.recipeIndex,i);assert.equal(q.recipeId,recipe.recipeId);assert.equal(q.sourceLevelId,recipe.sourceLevelId);for(const[k,v]of Object.entries(pr.slot))assert.deepEqual(q[k],v);assert.equal(q.formalReady,false);assert.equal(q.mathematicalEvidenceValidated,q.accepted);assert.equal(q.redesignRequired,!q.accepted);
    let built=null;if(q.constructionEvidence){built=await r.bound(q.constructionEvidence);assertWholeBoardConstruction(built,recipe);assert.deepEqual(built.nativeBindings,x.catalogue.assetBindings);assert.deepEqual(built.plan,pd);assert.equal(built.recipeId,recipe.recipeId);assert.equal(built.sourceLevelId,recipe.sourceLevelId);assert.deepEqual(q.level,built.level);assert.equal(q.levelSha256,built.levelSha256);assertWholeBoardAccounting(q.accounting);assertWholeBoardPhaseAccounting(built,q.accounting,q.joint);}
    else{assert(['WHOLEBOARD_NOT_STARTED_CONSUMED','WHOLEBOARD_FACTORY_PRECHECK_REFUSED'].includes(q.status));if(q.accounting){assertWholeBoardAccounting(q.accounting);for(const k of ['worlds','partialNodes','transitions','micro'])assert.equal(q.accounting[k],0);assert.deepEqual(q.accounting.reservations,[]);}else assert.equal(q.status,'WHOLEBOARD_NOT_STARTED_CONSUMED');assert.equal(q.level,null);assert.equal(q.levelSha256,null);}
    if(!q.level){assert.equal(q.accepted,false);for(const k of['levelSha256','attempt','proof','joint','lowerBound','route','drags','U','L'])assert.equal(q[k],null);}
    else{assert.equal(q.levelSha256,levelSha256(q.level));assertWholeBoardMechanisms(q.level,recipe);if(q.freshness)assert.deepEqual(q.freshness,x.index.check(q.level,pr.source,pr.parent));if(q.attempt){assert(q.freshness);assert.equal(built.status,'FIRST_FULL_AXIS_ICE_TERMINAL');}if(built.status!=='FIRST_FULL_AXIS_ICE_TERMINAL'){assert.equal(q.attempt,null);assert.equal(q.joint,null);}if(q.joint){assert.equal(q.staticAudit.passed,true);assert.equal(q.staticAudit.levelSha256,q.levelSha256);assertWholeBoardJointReceipt(q.joint,q.level,recipe,x.rt,q.accounting);assert.deepEqual(q.proof,q.joint.proof);assert.deepEqual(q.route,q.joint.route);assert.deepEqual(q.drags,q.joint.drags);assert.deepEqual(q.lowerBound,q.proof?{result:q.proof,method:'same-original-axis-ice-joint'}:null);}else{assert.equal(q.proof,null);assert.equal(q.route,null);assert.equal(q.drags,null);assert.equal(q.U,null);assert.equal(q.L,null);assert.equal(q.accepted,false);}if(q.accepted)assertWholeBoardAccepted(q,recipe,x.rt,pr.prior.level);x.index.add(q.level,q.constructionEvidence);}
    if(q.attempt){const files=publicFiles(q),req=await r.bound(await fd(files[0])),res=await r.bound(await fd(files[1])),sp=await r.bound(await fd(files[2])),sr=await r.bound(await fd(files[3])),identity=await r.bound(await fd(files[4]));assert.deepEqual(req,q.attempt);assert.equal(req.identityOrigin,req.id);assert.equal(req.redesignOf,pr.parent.request.id);assert.equal(req.levelSha256,q.levelSha256);assert.equal(identity.origin,req.id);assert.equal(res.accepted,q.accepted);assert.equal(res.status,q.status);assert.equal(res.levelSha256,q.levelSha256);assert.deepEqual(res.lower,q.lowerBound?.result);assert.deepEqual(res.upper,q.route?.search);assert.deepEqual(sr,q);assert.deepEqual(sp,{attempt:q.attempt,plan:pd,recipe,levelSha256:q.levelSha256,futureReservations:futureReservations(recipe),referenceLowerNotTransferred:true});if(!q.accepted)for(const f of files.slice(-2)){const b=await r.bound(await fd(f));assert.equal(b.attemptId,req.id);assert.equal(b.status,q.status);}}
   }
   assert.equal(subject.publicClaimsStarted,candidates.filter(q=>q.attempt).length);assert.equal(subject.accepted,candidates.filter(q=>q.accepted).length);assert.equal(subject.formedFullWorlds,candidates.filter(q=>q.level).length);const directory=path.dirname(subject.receipts[0].path),formed=candidates.filter(q=>q.level).map(q=>q.constructionEvidence);
   for(const[kind,od]of [['construction',subject.constructionOwner],['mathematical',subject.mathOwner]]){const o=await r.bound(od),expected=kind==='construction'?[...constructionFiles(pd,p),directory+'/execution-start.json',...candidates.filter(q=>q.constructionEvidence).map(q=>q.constructionEvidence.path)]:[...subject.receipts.map(x=>x.path),...candidates.flatMap(publicFiles)],attemptIds=kind==='mathematical'?candidates.filter(q=>q.attempt).map(q=>q.attempt.id):[];assertWholeBoardOwner(o,{kind,plan:pd,experimentId:p.experimentId,namespace:compileCanonicalHistoryPath(x.h.bundle.scope).canonical(path.resolve(kind==='construction'?LATE_PREFIX_CONSTRUCTION_LEDGER:PUBLIC_LEDGER)),attemptIds,files:expected});for(const f of o.files){assert.equal(sha(await r.bytes(f.path)),f.sha256);allowed.push(f.path);}if(kind==='construction'){assert.equal(o.closedCampaigns.length,1);const c=o.closedCampaigns[0],raw=await r.bound(c.descriptor);assertWholeBoardClosedCampaign(c,raw,{plan:pd,experimentId:p.experimentId,maximumInputs:p.maximumInputs,receipts:subject.receipts,formedWorldFiles:formed});}else assert.deepEqual(o.closedCampaigns,[]);}
  }await members(x.h,allowed);await x.r.finish();await r.finish();}catch(e){errors.push(e.stack??e.message);}
 const report={status:errors.length?'WHOLEBOARD_BATCH_AUDIT_FAILED':REVIEW_STATUS[mode],mode,plan:pd,...mode==='actual'?{completion:d,candidates:subject.receipts,accepted:candidates.filter(q=>q.accepted).length}:{},errors,toolBindings:Object.fromEntries(Object.entries(x.r.bindings).filter(([p])=>p.startsWith('tools/')||p.startsWith('src/'))),fileBindings:{...x.r.bindings,...r.bindings},newSearches:0,newConstructions:0,newReplayCalls:0,publicClaimsStarted:0,historyLoads:1,runtimeLoads:1,historicalBytesRevalidated:false,formalReady:false};await write(out,report);assert.equal(errors.length,0,errors.join('\n'));return report;}

if(process.argv[1]&&import.meta.url===pathToFileURL(path.resolve(process.argv[1])).href){const[mode,file,digest,out,reviewFile,reviewHash]=process.argv.slice(2),d={path:file,sha256:digest};if(mode==='prepare'){assert(!await exists(out));await fs.mkdir(out,{recursive:false});await write(out+'/plan.json',await prepareWholeBoardBatch(d));}else if(mode==='construct')await runWholeBoardBatch(d,out,{path:reviewFile,sha256:reviewHash});else if(mode?.startsWith('audit-'))await auditWholeBoardBatch(mode.slice(6),d,out);else throw Error('prepare / construct / audit-plan / audit-actual');}
